const Bebe:React.FC<{x?:number;y?:number;k?:number;rot?:number;llora?:number;s:number;sonrie?:number;manita?:number}>=({x=0,y=0,k=1,rot=0,llora=0,s,sonrie=0,manita=0})=><g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
